// A fragment holds a string of generated javascript that will be written
// to the destination. It also keeps hold of the original node from which
// it was generated. Using this node, when writing fragments in order, a
// mapping can be created of the original location => target location,
// aka, source-maps!
//
// These are generated by nodes, so will not have to create directly.
// Port of the former Ruby lib/opal/fragment.rb.
export class Fragment {
  // node: a Prism node (or compiler-made node with a location), null for
  // no location, or false to skip the fragment in source maps.
  constructor(code, scope, node = null) {
    this.code = String(code);
    this.scope = scope;
    this.node = node;
  }

  inspect() {
    return `f(${JSON.stringify(this.code)})`;
  }

  // The location the fragment maps back to: for calls the `.`/selector,
  // for blocks the opening brace, otherwise the node itself.
  get location() {
    const node = this.node;
    if (!node) return null;
    switch (node.type) {
      case "CallNode":
      case "OpalCall":
        return node.call_operator_loc || node.message_loc || node.location;
      case "BlockNode":
        return node.opening_loc || node.location;
      default:
        return node.location || null;
    }
  }

  skipSourceMap() {
    return this.node === false;
  }
}

// Post-processor directives (lib/opal/builder/post_processor.rb) travel in
// the fragment stream but generate no code.
export class Directive {
  constructor(name, params) {
    this.name = name;
    this.params = params;
    this.code = "";
  }
}

// Flattens nested arrays of fragments/directives.
export function flatten(list, out = []) {
  for (const item of list) {
    if (Array.isArray(item)) flatten(item, out);
    else if (item != null) out.push(item);
  }
  return out;
}
